        /// 에��터에서 데이터 리로드용 / For reloading data in editor
        /// </summary>
        [ContextMenu("Reload CSV Data")]
        private void ReloadCSVData()
        {
            // 외부 CSV 로드 방식으로 변경되어 이 기능은 더 이상 사용하지 않음
        }
    }
