using UnityEngine;

namespace Dialogue
{
    /// <summary>
    /// 대화 상호작용 가능한 오브젝트
    /// 특정 CSV 대화 데이터와 연결됨
    /// </summary>
    public class DialogueTarget : MonoBehaviour
    {
        [Header("대화 설정")]
        [SerializeField] private TextAsset dialogueCSV;  // 대화 CSV 파일
        [SerializeField] private int startDialogueId;     // 시작 대화 ID

        /// <summary>
        /// 대화 CSV 데이터 (읽기 전용)
        /// </summary>
        public TextAsset DialogueCSV => dialogueCSV;

        /// <summary>
        /// 시작 대화 ID (읽기 전용)
        /// </summary>
        public int StartDialogueId => startDialogueId;

        /// <summary>
        /// 대화 시작 시도
        /// </summary>
        /// <param name="dialogueManager">대화 매니저</param>
        /// <returns>대화 시작 성공 여부</returns>
        public bool TryStartDialogue(DialogueManager dialogueManager)
        {
            if (dialogueManager == null || dialogueCSV == null)
            {
                return false;
            }

            // 대화 매니저에 CSV 로드 및 시작
            dialogueManager.LoadAndStartDialogue(dialogueCSV, startDialogueId);
            return true;
        }
    }
}

using UnityEngine;

namespace Dialogue
{
    /// <summary>
    /// 다이얼로그 시스템 테스트용 스크립트 / Dialogue System Test Script
    /// 게임 시작 시 자동으로 다이얼로그를 시작하는 예시
    /// </summary>
    public class DialogueTester : MonoBehaviour
    {
        [Header("테스트 설정 / Test Settings")]
        [SerializeField] private DialogueManager dialogueManager;  // 다이얼로그 매니저 참조
        [SerializeField] private int startDialogueId = 100;        // 시작할 다이얼로그 ID
        [SerializeField] private bool autoStartOnAwake = true;     // 시작 시 자동 실행 여부

        /// <summary>
        /// 초기화 시 자동 시작 / Auto start on initialization
        /// </summary>
        private void Start()
        {
            if (autoStartOnAwake && dialogueManager != null)
            {
                // 약간의 지연 후 다이얼로그 시작 (UI 초기화 대기)
                Invoke(nameof(StartTestDialogue), 0.1f);
            }
        }

        /// <summary>
        /// 테스트 다이얼로그 시작 / Start test dialogue
        /// </summary>
        public void StartTestDialogue()
        {
            if (dialogueManager != null)
            {
                dialogueManager.StartDialogue(startDialogueId);
            }
            else
            {
                Debug.LogError("DialogueManager is not assigned to DialogueTester");
            }
        }

        /// <summary>
        /// 키보드 입력으로 다이얼로그 테스트 / Test dialogue with keyboard input
        /// </summary>
        private void Update()
        {
            // T 키로 다이얼로그 재시작
            if (Input.GetKeyDown(KeyCode.T))
            {
                StartTestDialogue();
            }

            // ESC 키로 다이얼로그 강제 종료
            if (Input.GetKeyDown(KeyCode.Escape))
            {
                if (dialogueManager != null)
                {
                    dialogueManager.ForceEndDialogue();
                }
            }
        }
    }
}

using UnityEngine;

namespace Dialogue
{
    /// <summary>
    /// 다이얼로그 시스템 테스트용 스크립트 / Dialogue System Test Script
    /// 게임 시작 시 자동으로 다이얼로그를 시작하는 예시
    /// </summary>
    public class DialogueTester : MonoBehaviour
    {
        [Header("테스트 설정 / Test Settings")]
        [SerializeField] private DialogueManager dialogueManager;  // 다이얼로그 매니저 참조
        [SerializeField] private TextAsset testDialogueCSV;        // 테스트용 CSV 파일
        [SerializeField] private int startDialogueId = 100;        // 시작할 다이얼로그 ID
        [SerializeField] private bool autoStartOnAwake = true;     // 시작 시 자동 실행 여부

        /// <summary>
        /// 초기화 시 자동 시작 / Auto start on initialization
        /// </summary>
        private void Start()
        {
            if (autoStartOnAwake && dialogueManager != null)
            {
                // 약간의 지연 후 다이얼로그 시작 (UI 초기화 대기)
                Invoke(nameof(StartTestDialogue), 0.1f);
            }
        }

        /// <summary>
        /// 테스트 다이얼로그 시작 / Start test dialogue
        /// </summary>
        public void StartTestDialogue()
        {
            if (dialogueManager == null)
            {
                Debug.LogError("DialogueManager is not assigned to DialogueTester");
                return;
            }

            if (testDialogueCSV == null)
            {
                Debug.LogError("Test Dialogue CSV is not assigned to DialogueTester");
                return;
            }

            // CSV를 로드하고 다이얼로그 시작
            dialogueManager.LoadAndStartDialogue(testDialogueCSV, startDialogueId);
        }

        /// <summary>
        /// 키보드 입력으로 다이얼로그 테스트 / Test dialogue with keyboard input
        /// </summary>
        private void Update()
        {
            // T 키로 다이얼로그 재시작
            if (Input.GetKeyDown(KeyCode.T))
            {
                StartTestDialogue();
            }

            // ESC 키로 다이얼로그 강제 종료
            if (Input.GetKeyDown(KeyCode.Escape))
            {
                if (dialogueManager != null)
                {
                    dialogueManager.ForceEndDialogue();
                }
            }
        }
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.InputSystem;

namespace Dialogue
{
    /// <summary>
    /// 플레이어 대화 상호작용 시스템
    /// 트리거 영역 내 대화 가능한 오브젝트 감지 및 상호작용 키로 대화 시작
    /// 필수: CharacterController/Rigidbody + Trigger Collider
    /// </summary>
    public class PlayerDialogueInteractor : MonoBehaviour
    {
        [SerializeField] private DialogueManager dialogueManager; // 대화 매니저

        private InputAction interactAction; // 상호작용 입력 액션 (E키, 게임패드 버튼)
        private readonly List<DialogueTarget> candidates = new(); // 대화 가능 범위 내 오브젝트 목록

        /// <summary>
        /// 활성화 시 상호작용 입력 설정 및 이벤트 바인딩
        /// </summary>
        private void OnEnable()
        {
            // 상호작용 입력 설정: E키와 게임패드 남쪽 버튼
            interactAction = new InputAction("Interact", InputActionType.Button, "<Keyboard>/e");
            interactAction.AddBinding("<Gamepad>/buttonSouth");
            interactAction.performed += OnInteractPerformed;
            interactAction.Enable();
        }

        /// <summary>
        /// 비활성화 시 입력 액션 정리 및 메모리 해제
        /// </summary>
        private void OnDisable()
        {
            if (interactAction != null)
            {
                interactAction.performed -= OnInteractPerformed;
                interactAction.Disable();
                interactAction.Dispose();
            }
        }

        /// <summary>
        /// 트리거 진입: 대화 가능한 오브젝트를 후보 목록에 추가
        /// </summary>
        private void OnTriggerEnter(Collider other)
        {
            if (other.TryGetComponent<DialogueTarget>(out var dialogueTarget))
            {
                if (!candidates.Contains(dialogueTarget))
                    candidates.Add(dialogueTarget);
            }
        }

        /// <summary>
        /// 트리거 탈출: 범위를 벗어난 오브젝트를 후보 목록에서 제거
        /// </summary>
        private void OnTriggerExit(Collider other)
        {
            if (other.TryGetComponent<DialogueTarget>(out var dialogueTarget))
                candidates.Remove(dialogueTarget);
        }

        /// <summary>
        /// 상호작용 키 입력 처리: 가장 가까운 대화 오브젝트와 대화 시작
        /// </summary>
        private void OnInteractPerformed(InputAction.CallbackContext context)
        {
            if (dialogueManager == null) return;

            // 이미 대화 중이면 무시
            if (dialogueManager.IsDialogueActive()) return;

            var nearest = GetNearestCandidate();
            if (nearest != null && nearest.TryStartDialogue(dialogueManager))
                candidates.Remove(nearest); // 대화 시작 성공 시 목록에서 제거 (선택���)
        }

        /// <summary>
        /// 후보 목록에서 플레이어와 가장 가까운 대화 대상 찾기
        /// </summary>
        private DialogueTarget GetNearestCandidate()
        {
            // 파괴된 오브젝트 정리 (null 참조 방지)
            candidates.RemoveAll(c => c == null);

            if (candidates.Count == 0) return null;

            // 가장 가까운 대화 대상 찾기 (거리 기반 비교)
            var nearest = candidates[0];
            var nearestDist = Vector3.Distance(transform.position, nearest.transform.position);

            for (int i = 1; i < candidates.Count; i++)
            {
                var dist = Vector3.Distance(transform.position, candidates[i].transform.position);
                if (dist < nearestDist)
                {
                    nearest = candidates[i];
                    nearestDist = dist;
                }
            }

            return nearest;
        }
    }
}
